window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[37]={"id":"037","numero":37,"titre":"Interruption volontaire de grossesse","objectifs":[{"id":"37-1","rang":"A","rubrique":"Définition","titre":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","contenu":"<p>Repères chronologiques de l’<span class=\"kw-clinique\">évolution</span> du <span class=\"kw-def\">cadre légal français</span> autour de la contraception et de l’avortement, depuis la <span class=\"kw-def\">loi Neuwirth (1967)</span> jusqu’à la <span class=\"kw-def\">constitutionnalisation (8 mars 2024)</span>. Contenu strictement factuel et médico-légal.</p>\n\n      <table >\n        <thead>\n          <tr><th>Date</th><th>Évolution</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1967</strong> — Loi Neuwirth</td>\n            <td><span class=\"kw-def\">Autorise la contraception</span> en France. Loi <strong>réellement appliquée à partir de 1974</strong> seulement (décrets d’application tardifs).</td>\n          </tr>\n          <tr>\n            <td><strong>Avant 1975</strong></td>\n            <td>\n              <strong>Avortement :</strong> acte <span class=\"kw-alerte\">réprimé par la loi</span>, passible de prison.<br>\n              <strong>Conséquence :</strong> l’avortement clandestin n’avait pas disparu — il était responsable de <span class=\"kw-chiffre\">&gt; 250 décès/an</span> de femmes.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>17 janvier 1975</strong> — Loi Veil</td>\n            <td>Loi qui <span class=\"kw-def\">dépénalise l’avortement</span> est adoptée.</td>\n          </tr>\n          <tr>\n            <td><strong>1979</strong></td>\n            <td>Création des <span class=\"kw-def\">centres d’IVG</span> pour permettre aux femmes de recourir à l’avortement dans un lieu approprié.</td>\n          </tr>\n          <tr>\n            <td><strong>8 mars 2024</strong> — Loi constitutionnelle</td>\n            <td>Inscription dans la <span class=\"kw-def\">Constitution de 1958</span> de la <strong>liberté garantie des femmes de recourir à l’IVG</strong> → réaffirmation du caractère fondamental de cette liberté en France.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span class=\"kw-clinique\">loi Veil de 1975</span> ne légalise pas l’IVG, elle la <strong>dépénalise</strong>. La loi de mars 2024 a ensuite consacré la liberté de recourir à l’IVG dans la <strong>Constitution</strong> — la France est le 1er pays à inscrire cette liberté à son niveau constitutionnel.\n      </div>","frequence":0},{"id":"37-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes de grossesses non désirées","contenu":"<p>Les <span class=\"kw-def\">causes de grossesses non désirées</span> ne se résument pas à l’absence de contraception : <strong>2 femmes sur 3 (≈<span class=\"kw-chiffre\"> 66 %</span>)</strong> ayant recours à une IVG <span class=\"kw-clinique\">utilisaient une méthode contraceptive</span> au moment de la <span class=\"kw-ci\">grossesse</span>. Le problème tient donc surtout à un <strong>échec ou une inadaptation</strong> de la contraception.</p>\n\n      <h4>Les 3 causes officielles (CNGOF)</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-def\">Absence de contraception</span>.</strong></li>\n        <li><strong><span class=\"kw-def\">Changement de méthode</span></strong> contraceptive — période de transition à risque.</li>\n        <li><strong><span class=\"kw-def\">Méthode non adaptée</span></strong> — méthode peu efficace ou mal utilisée au regard du mode de vie (oubli de pilule, retard patch/anneau, retrait, méthodes naturelles…).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong>\n        <ul>\n          <li><span class=\"kw-chiffre\">&gt; 60 %</span> des femmes réalisant une IVG avaient une <strong>couverture contraceptive</strong> en début de <span class=\"kw-ci\">grossesse</span> → l’<strong>échec/inadaptation</strong> prime sur l’absence.</li>\n          <li>La <strong><span class=\"kw-ci\">grossesse</span> non désirée ne mène pas toujours à l’IVG</strong> : aujourd’hui <span class=\"kw-chiffre\">≈ 60 %</span> des femmes confrontées à une grossesse non prévue choisissent de l’interrompre, contre <span class=\"kw-chiffre\">40 %</span> en 1975.</li>\n          <li>La stabilité du nombre d’IVG ne traduit <span class=\"kw-alerte\">pas un échec de la contraception</span>, mais une hausse de la propension à recourir à l’IVG en cas de <span class=\"kw-ci\">grossesse</span> non désirée.</li>\n        </ul>\n      </div>\n\n      <p><em>Complément hors fiche Notion (muette sur cet objectif) — Source : Collège CNGOF de Gynécologie-Obstétrique, 5ᵉ éd., item 37.</em></p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":0},{"id":"37-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître le nombre d’IVG réalisés en France","contenu":"<p>Chiffres-clés de l’<span class=\"kw-def\">épidémiologie</span> de l’IVG en France (données <span class=\"kw-chiffre\">2019</span>) :</p>\n\n      <ul>\n        <li><strong>Nombre annuel d’IVG en France :</strong> <span class=\"kw-chiffre\">230 000 IVG</span> (en 2019).</li>\n        <li><strong>Tendance :</strong> <span class=\"kw-def\">incidence</span> <span class=\"kw-def\">relativement stable</span>, avec <strong>légère augmentation</strong> en 2019.</li>\n        <li><strong>Rapport aux naissances :</strong> <span class=\"kw-chiffre\">1 IVG pour 3 naissances</span>.</li>\n        <li><strong>Proportion de femmes y ayant recours dans leur vie :</strong> <span class=\"kw-chiffre\">40 %</span>.</li>\n        <li><strong>Sous contraception lors de l’IVG :</strong> <span class=\"kw-chiffre\">&gt; 60 %</span> des femmes (= échec/défaut d’utilisation de la contraception, pas absence).</li>\n      </ul>\n\n      <h4>Géographie</h4>\n\n      <p>Zones où les <span class=\"kw-clinique\">taux d’IVG sont les plus élevés</span> :</p>\n\n      <ul>\n        <li><strong>DROM</strong> (départements/régions d’outre-mer)</li>\n        <li><strong>Île-de-France</strong></li>\n        <li><strong>Sud-Est</strong> (PACA, Corse)</li>\n      </ul>\n\n      <h4>Méthode</h4>\n\n      <ul>\n        <li><strong>IVG médicamenteuses :</strong> <span class=\"kw-chiffre\">70 %</span> des IVG, <strong>en hausse</strong> continue.</li>\n        <li><strong>Voie instrumentale (chirurgicale) :</strong> recours <strong>en diminution</strong> continue.</li>\n      </ul>\n\n      <h4>Délais et terme</h4>\n\n      <ul>\n        <li><strong>Délai entre 1ère demande d’IVG et réalisation :</strong> <span class=\"kw-chiffre\">7,5 jours</span> en moyenne.</li>\n        <li><strong>Terme :</strong> <span class=\"kw-chiffre\">≥ 50 %</span> des IVG réalisées <strong>avant la 7ᵉ semaine de <span class=\"kw-ci\">grossesse</span></strong>.</li>\n        <li><strong>Hors structure hospitalière :</strong> <span class=\"kw-chiffre\">25 %</span> des IVG sont réalisées en ville.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":0},{"id":"37-4","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’âge de la population réalisant le plus d’IVG","contenu":"<p>Distribution par <span class=\"kw-def\">tranche d’âge</span> du recours à l’IVG en France :</p>\n\n      <ul>\n        <li><strong>Tranche d’âge la plus concernée :</strong> <span class=\"kw-chiffre\">20-29 ans</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Évolution</span> selon l’âge :</strong>\n          <ul>\n            <li><strong>&lt;<span class=\"kw-chiffre\"> 20 ans</span> :</strong> <span class=\"kw-def\">incidence</span> <span class=\"kw-clinique\">en baisse</span>.</li>\n            <li><strong><span class=\"kw-chiffre\">20-25 ans</span> :</strong> <span class=\"kw-def\">incidence</span> <span class=\"kw-clinique\">stable</span>.</li>\n            <li><strong>Femmes plus âgées :</strong> <span class=\"kw-def\">incidence</span> <span class=\"kw-clinique\">en hausse</span>.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Lecture EDN.</strong> La tranche <span class=\"kw-chiffre\">20-29 ans</span> est l’âge médian du recours, en cohérence avec l’âge médian du premier rapport et la mise en couple. La <strong>baisse chez les &lt;<span class=\"kw-chiffre\"> 20 ans</span></strong> traduit l’amélioration de l’accès à la contraception/contraception d’<span class=\"kw-alerte\">urgence</span> chez les adolescentes (<span class=\"kw-ttt\">Norlevo</span> / <span class=\"kw-ttt\">EllaOne</span> en accès libre, gratuité &lt;<span class=\"kw-chiffre\"> 26 ans</span>).\n      </div>","frequence":0},{"id":"37-5","rang":"A","rubrique":"Définition","titre":"Connaître les conditions de pratique des IVG en France","contenu":"<p>Objectif <span class=\"kw-def\">central</span> de l’item — tombe régulièrement aux QCM EDN (⭐⭐⭐⭐). Les conditions de pratique de l’IVG sont strictement encadrées par la loi Veil et ses révisions successives.</p>\n\n      <table >\n        <thead>\n          <tr><th>Item réglementaire</th><th>Règle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Consentement</strong></td>\n            <td>\n              <strong>Consentement écrit de la femme</strong> uniquement (<span class=\"kw-alerte\">pas du conjoint</span>).<br>\n              <strong>Choix :</strong> incombe à la femme ; les équipes médicales s’assurent que son autonomie de décision est préservée.<br>\n              <strong>Conjoint :</strong> peut participer à la consultation si la femme le souhaite, mais le consentement est recueilli <strong>en dehors de sa présence</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Entretien psychosocial</strong></td>\n            <td>\n              <strong>Proposé systématiquement</strong> à toute femme par un professionnel qualifié (conseils appropriés à la situation).<br>\n              <strong>Obligatoire :</strong> uniquement pour la <span class=\"kw-clinique\">femme mineure non émancipée</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Délai de réflexion</strong> ⭐</td>\n            <td>\n              L’IVG peut se décider <span class=\"kw-def\">sans délai</span>.<br>\n              <strong>Suppression du délai de <span class=\"kw-chiffre\">2 jours</span></strong> après entretien psychosocial, <span class=\"kw-chiffre\">depuis 2022</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mineure non émancipée</strong></td>\n            <td>\n              Accompagnement obligatoire d’<strong>1 personne majeure</strong> au choix de la mineure (pas forcément les représentants légaux).<br>\n              Rôle de la personne majeure : <strong>accompagnement/soutien uniquement</strong> — <span class=\"kw-alerte\">aucune responsabilité civile/pénale</span>.<br>\n              <strong>Entretien psychosocial obligatoire</strong> pour la mineure non émancipée.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Étrangère</strong></td>\n            <td>L’IVG n’est soumise à <strong>aucune condition de durée ni de régularité du séjour</strong> sur le territoire français.</td>\n          </tr>\n          <tr>\n            <td><strong>Déclaration</strong></td>\n            <td>\n              Déclaration établie par médecin ou sage-femme, adressée par l’établissement à l’<span class=\"kw-def\">ARS</span>.<br>\n              <span class=\"kw-alerte\">Aucune mention de l’identité de la femme</span> sur la déclaration.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Remboursement</strong></td>\n            <td>\n              <strong>Prise en charge à<span class=\"kw-chiffre\"> 100 %</span></strong> par l’Assurance maladie.<br>\n              <strong>Inclut :</strong> IVG ; <span class=\"kw-imagerie\">échographie</span> préalable ; <span class=\"kw-imagerie\">échographie</span> de contrôle ; bilan sanguin.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Contraception</strong> ⭐</td>\n            <td>\n              Information et accès à la contraception <strong>proposés lors d’une consultation dédiée à l’issue de l’IVG</strong>.<br>\n              <span class=\"kw-alerte\">PIÈGE QCM :</span> l’information contraception se fait à la <strong>2ème consultation</strong>, <span class=\"kw-alerte\">pas à la 1ère</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Dossier-guide</strong></td>\n            <td>\n              <strong>ARS</strong> assure la réalisation, la <span class=\"kw-imagerie\">diffusion</span> et la mise à jour annuelle du dossier-guide.<br>\n              <strong>Médecin/sage-femme :</strong> remet le dossier-guide à la patiente lors de la <strong>1ère consultation</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conservation des documents</strong></td>\n            <td>\n              <strong>Quoi ?</strong> Attestations de consultation ; confirmation de demande d’IVG.<br>\n              <strong>Qui ?</strong> Direction de l’établissement de santé.<br>\n              <strong>Durée ?</strong> <span class=\"kw-chiffre\">≥ 1 an</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>PIÈGE QCM ⭐ — à connaître par cœur.</strong>\n        <ul>\n          <li>Le <strong>délai de <span class=\"kw-chiffre\">48 h</span> post-entretien</strong> psychosocial a été <span class=\"kw-alerte\">supprimé en 2022</span> — l’IVG peut donc se décider sans aucun délai.</li>\n          <li>L’<strong>information contraception</strong> se fait à la <span class=\"kw-alerte\">2ème consultation, pas à la 1ère</span>.</li>\n          <li>L’entretien psychosocial n’est <strong>obligatoire</strong> que pour la <span class=\"kw-clinique\">mineure non émancipée</span>.</li>\n          <li>Le consentement du <span class=\"kw-alerte\">conjoint n’est jamais requis</span>.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 36 — Contraception</em></p>","frequence":4},{"id":"37-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les structures de prise en charge des IVG","contenu":"<p>Les structures et professionnels habilités à prendre en charge une IVG sont définis par la loi, avec des différences nettes entre <span class=\"kw-def\">IVG médicamenteuse</span> (réalisable en ville) et <span class=\"kw-def\">IVG chirurgicale</span> (établissement de santé uniquement).</p>\n\n      <h4>Délais maximums autorisés</h4>\n\n      <table >\n        <thead>\n          <tr><th>Technique</th><th>Délai maximum</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>IVG médicamenteuse</strong></td>\n            <td><span class=\"kw-chiffre\">7 semaines de grossesse</span> (= <span class=\"kw-chiffre\">9 SA</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>IVG chirurgicale</strong></td>\n            <td><span class=\"kw-chiffre\">14 semaines de grossesse</span> (= <span class=\"kw-chiffre\">16 SA</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Professionnels habilités</h4>\n\n      <table >\n        <thead>\n          <tr><th>Acte</th><th>Médecin</th><th>Sage-femme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Consultations</strong></td>\n            <td>Oui (toutes consultations)</td>\n            <td>Oui — sauf <span class=\"kw-alerte\">2ème consultation pour IVG chirurgicale &gt; 12 SA</span> (réservée au médecin)</td>\n          </tr>\n          <tr>\n            <td><strong>IVG médicamenteuse</strong></td>\n            <td>Oui</td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td><strong>IVG chirurgicale</strong></td>\n            <td>Oui</td>\n            <td>Oui, jusqu’à <span class=\"kw-chiffre\">≤ 12 SA</span> (depuis 2022)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Clause de conscience et entrave</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Clause de conscience.</strong> Le médecin ou la sage-femme n’est <span class=\"kw-def\">pas tenu</span> de pratiquer une IVG. En cas de refus, il/elle a l’<strong>obligation de communiquer immédiatement le nom et les coordonnées d’autres praticiens ou sages-femmes</strong> susceptibles de la réaliser.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Entrave à l’IVG.</strong> Empêcher ou tenter d’empêcher une IVG par <span class=\"kw-alerte\">menace</span> ou <span class=\"kw-imagerie\">diffusion</span> d’allégations à but dissuasif = <span class=\"kw-alerte\">délit sanctionnable</span> par la loi.\n      </div>\n\n      <h4>Structures — IVG médicamenteuse en ville</h4>\n\n      <p>IVG médicamenteuse possible <strong>en ville jusqu’à 9 SA</strong> :</p>\n\n      <ul>\n        <li><span class=\"kw-ttt\">Mifépristone</span> disponible en <strong>pharmacie d’officine</strong>, délivrance <span class=\"kw-alerte\">strictement réservée</span> aux médecins/sages-femmes autorisés.</li>\n        <li>Médecin/sage-femme doit être <strong>conventionné</strong> à un établissement de santé.</li>\n        <li>Conditions de conventionnement (alternative) :\n          <ul>\n            <li>Soit <strong>qualifié en gynécologie médicale ou en gynécologie-obstétrique</strong>.</li>\n            <li>Soit <strong>justifier d’une pratique suffisante et régulière des IVG médicamenteuses</strong> en établissement de santé.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Structures — Établissements de santé</h4>\n\n      <ul>\n        <li>Établissements <strong>publics ne peuvent pas refuser</strong> de pratiquer des IVG.</li>\n        <li><strong>Ligne téléphonique dédiée</strong> à cette activité dans chaque établissement.</li>\n        <li>Toute patiente doit obtenir un <strong>RDV de consultation dans les <span class=\"kw-chiffre\">5 jours</span> suivant son appel</strong>.</li>\n        <li>Lits en gynéco-obstétrique ou en <span class=\"kw-ttt\">chirurgie</span> disponibles si complication.</li>\n        <li>IVG réalisée en <span class=\"kw-def\">hôpital de jour</span> (séjour <span class=\"kw-chiffre\">&lt; 12 h</span>).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>IVG chirurgicale en ville : <span class=\"kw-ci\">interdite</span>.</strong> L’IVG chirurgicale <span class=\"kw-alerte\">ne peut être réalisée qu’en établissement</span> de santé public ou privé agréé.\n      </div>\n\n      <h4>Anonymat</h4>\n\n      <table >\n        <thead>\n          <tr><th>Lieu</th><th>Garantie d’anonymat</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>En ville</strong></td>\n            <td>Anonymat garanti <strong>uniquement pour les femmes mineures</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Hôpital</strong></td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span> peut garantir l’anonymat sur les relevés de sécurité sociale pour <strong>femmes majeures ET mineures</strong>.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"37-7","rang":"A","rubrique":"Prise en charge","titre":"Décrire les étapes de la prise en charge","contenu":"<p>La prise en charge IVG suit un schéma en <span class=\"kw-def\">3 consultations</span> standardisées : 1ère consultation (formulation de la demande) → 2ème consultation (confirmation et réalisation) → consultation de contrôle post-IVG.</p>\n\n      <h4>1ère consultation — Formulation de la demande</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Professionnels</strong></td>\n            <td>Médecin <strong>ou</strong> sage-femme.</td>\n          </tr>\n          <tr>\n            <td><strong>Informations</strong></td>\n            <td>\n              <strong>Entretien psychosocial :</strong> proposé systématiquement, <span class=\"kw-alerte\">obligatoire pour mineure non émancipée</span>.<br>\n              <strong>Information :</strong> procédures possibles, choix de recours à l’anesthésie locale ou générale.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Documents</strong></td>\n            <td>Dossier-guide ; attestation de 1ère consultation — <strong>remis à la patiente</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Prescriptions</strong></td>\n            <td>\n              <strong>Groupe sanguin :</strong> ABO, Rh.<br>\n              <strong>RAI.</strong><br>\n              <strong><span class=\"kw-imagerie\">Échographie</span> de datation :</strong> <span class=\"kw-bio\">non indispensable</span>, mais nécessaire si doute sur le terme ou la localisation.<br>\n              <strong><span class=\"kw-bio\">PCR</span> :</strong> <span class=\"kw-clinique\">Chlamydia trachomatis + gonocoque</span> sur prélèvement vaginal — <span class=\"kw-def\">recommandé avant toute IVG</span>.<br>\n              <strong>FCV :</strong> peut être proposé.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2ème consultation — Confirmation et réalisation de l’IVG</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Déroulement</strong></td>\n            <td>\n              <strong>Vérification de la datation :</strong> IVG autorisée si <span class=\"kw-chiffre\">LCC ≤ 90 mm</span> et/ou <span class=\"kw-chiffre\">BIP ≤ 30 mm</span>.<br>\n              <strong>Recueil du consentement écrit</strong> de la demande d’IVG.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Réalisation IVG</strong></td>\n            <td>\n              <strong>Médicamenteuse :</strong> prise de <span class=\"kw-ttt\">mifépristone</span> au terme de la consultation + remise du <span class=\"kw-ttt\">misoprostol</span> pour prise au domicile.<br>\n              <strong>Chirurgicale :</strong> préparation cervicale ± consultation d’anesthésie si AG prévue → IVG réalisée <span class=\"kw-chiffre\">36-48 h plus tard</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Contraception post-IVG</strong> ⭐</td>\n            <td>\n              Information et choix de la méthode contraceptive <span class=\"kw-alerte\">se fait lors de la 2ème consultation</span> (pas la 1ère).<br>\n              <strong>Anneau vaginal :</strong> possible <span class=\"kw-chiffre\">5 jours après</span> IVG.<br>\n              <strong>DIU :</strong> possible <span class=\"kw-chiffre\">10 jours après</span> IVG médicamenteuse (après vérification de la vacuité utérine).<br>\n              Autres méthodes : possibles le jour même de l’IVG.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prescriptions</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">&lt; 72 h</span> pour toute IVG <strong>si femme Rh-</strong> ;<br>\n              <span class=\"kw-ttt\">Antalgiques</span> (<span class=\"kw-ttt\">AINS</span> ++) ;<br>\n              Contraception choisie.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Consultation de contrôle post-IVG</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Quand ?</strong></td>\n            <td><span class=\"kw-chiffre\">J14 - J21</span> après l’IVG.</td>\n          </tr>\n          <tr>\n            <td><strong>Obligatoire ?</strong></td>\n            <td>\n              <strong>Obligatoire</strong> selon gynécologie médicale Medline ;<br>\n              <strong>Conseillée mais non obligatoire</strong> selon gynéco-obstétrique Masson.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Objectifs</strong></td>\n            <td>\n              <strong>Vérifier la réussite de l’IVG médicamenteuse :</strong> contrôle <span class=\"kw-bio\">β-hCG</span> ou contrôle <span class=\"kw-imagerie\">échographique</span> de vacuité utérine.<br>\n              Faire le point sur la contraception prescrite ;<br>\n              Rechercher des complications.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>PIÈGE QCM ⭐.</strong> L’information sur la <span class=\"kw-alerte\">contraception ne se fait pas à la 1ère consultation</span> mais à la 2ème — le piège classique aux QCM. L’<span class=\"kw-clinique\">échographie de datation</span> n’est <span class=\"kw-bio\">pas indispensable</span> à la 1ère consultation (seulement si doute sur terme/localisation).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 162 — IST</em></p>","frequence":2},{"id":"37-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les techniques d’IVG médicamenteuse et chirurgicale","contenu":"<p>Deux techniques distinctes — choix selon l’<span class=\"kw-def\">âge gestationnel</span>, le choix de la patiente et les <span class=\"kw-def\">contre-indications</span>. Les différences en termes de succès, EI et lésions d’organes sont <strong>très faibles</strong> : la femme doit pouvoir choisir la méthode quand c’est possible.</p>\n\n      <h4>IVG médicamenteuse — Médicaments</h4>\n\n      <table >\n        <thead>\n          <tr><th></th><th><span class=\"kw-ttt\">Mifépristone</span></th><th><span class=\"kw-ttt\">Misoprostol</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Quand ?</strong></td>\n            <td><em>Administrée au terme de la consultation</em></td>\n            <td><em>Administré <span class=\"kw-chiffre\">24-48 h après</span> la mifépristone</em></td>\n          </tr>\n          <tr>\n            <td><strong>Voie</strong></td>\n            <td>PO</td>\n            <td>Transmuqueuse PO ou sublinguale</td>\n          </tr>\n          <tr>\n            <td><strong>Classe</strong></td>\n            <td>\n              <span class=\"kw-def\">Stéroïde de synthèse</span> à fortes propriétés <strong>antiprogestérones</strong> (affinité pour les récepteurs de la progestérone <span class=\"kw-chiffre\">5× supérieure</span> à celle de la progestérone elle-même).\n            </td>\n            <td>\n              <span class=\"kw-def\">Analogue de la prostaglandine PGE1</span>.<br>\n              <em>(Les prostaglandines servent à provoquer des contractions ; les <span class=\"kw-ttt\">AINS</span> inhibent leur synthèse et étaient utilisés autrefois comme tocolytiques.)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mode d’action</strong></td>\n            <td>\n              La progestérone est indispensable au développement et au maintien initial de la <span class=\"kw-ci\">grossesse</span> (rôle du corps jaune) :\n              <ul>\n                <li><span class=\"kw-clinique\">Nécrose déciduale</span> provoquant un <span class=\"kw-clinique\">détachement de l’œuf</span>.</li>\n                <li>Stimule la sécrétion des <strong>prostaglandines endogènes</strong> → <strong>contractions utérines</strong> + <strong>ouvre et ramollit le col</strong>.</li>\n              </ul>\n            </td>\n            <td>\n              Stimule la contractilité utérine par liaison aux récepteurs spécifiques dans le myomètre ; entraîne l’expulsion de l’œuf grâce à :\n              <ul>\n                <li><strong>Relâchement du col utérin.</strong></li>\n                <li><strong>Contractions des fibres musculaires lisses du myomètre.</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>IVG médicamenteuse — Déroulement</h4>\n\n      <ul>\n        <li><strong>Protocole :</strong>\n          <ol>\n            <li><span class=\"kw-ttt\">Mifépristone</span> PO <strong>au terme de la consultation</strong>.</li>\n            <li><span class=\"kw-ttt\">Misoprostol</span> par voie transmuqueuse PO ou sublinguale <strong>après <span class=\"kw-chiffre\">24-48 h</span></strong>.</li>\n          </ol>\n        </li>\n        <li><strong>Saignements (expulsion du fœtus) :</strong>\n          <ul>\n            <li>Après mifépristone : saignement possible.</li>\n            <li>Après misoprostol (expulsion) : <span class=\"kw-chiffre\">2-4 h après</span> dans <span class=\"kw-chiffre\">60 %</span> des cas, ou <span class=\"kw-chiffre\">24-72 h</span> dans <span class=\"kw-chiffre\">40 %</span> des cas.</li>\n            <li><strong>Saignement très abondant ne doit pas excéder <span class=\"kw-chiffre\">2-4 h</span>.</strong></li>\n            <li>Durée moyenne du saignement : <span class=\"kw-chiffre\">10-13 jours</span>, peut durer jusqu’aux règles suivantes.</li>\n          </ul>\n        </li>\n        <li><strong>Douleurs (contractions utérines) :</strong>\n          <ul>\n            <li>Maximales <span class=\"kw-chiffre\">1-3 h après la prise de misoprostol</span>.</li>\n            <li>Décroissent puis disparaissent peu après l’expulsion complète.</li>\n            <li>CAT : <span class=\"kw-ttt\">ibuprofène</span> ou <span class=\"kw-ttt\">paracétamol + codéine</span> — <span class=\"kw-alerte\">pas de paracétamol seul</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Contrôle du succès :</strong>\n          <ul>\n            <li>Soit <span class=\"kw-imagerie\">contrôle échographique</span>.</li>\n            <li>Soit <span class=\"kw-bio\">β-hCG plasmatique ou urinaire</span> : succès si <span class=\"kw-chiffre\">baisse &gt; 80 % à J15</span> par rapport au dosage initial.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>IVG chirurgicale (instrumentale) — Déroulement</h4>\n\n      <ul>\n        <li><strong>Rappels :</strong>\n          <ul>\n            <li>Autorisée jusqu’à <span class=\"kw-chiffre\">16 SA</span> (<span class=\"kw-chiffre\">14 semaines</span> de <span class=\"kw-ci\">grossesse</span>).</li>\n            <li>Uniquement en établissement de santé public ou privé agréé.</li>\n            <li>Sage-femme habilitée jusqu’à <span class=\"kw-chiffre\">≤ 12 SA</span> depuis 2022.</li>\n          </ul>\n        </li>\n        <li><strong>Préparation cervicale :</strong> <span class=\"kw-def\">systématiquement recommandée</span> avant dilatation :\n          <ul>\n            <li><strong>Objectif :</strong> réduire le temps opératoire et les complications rares.</li>\n            <li><strong>Comment ?</strong> <span class=\"kw-ttt\">Mifépristone</span> ou <span class=\"kw-ttt\">misoprostol</span> délivré <span class=\"kw-chiffre\">36-48 h avant</span> l’intervention.</li>\n          </ul>\n        </li>\n        <li><strong>Orientation :</strong> <span class=\"kw-def\">ambulatoire</span> (pas d’<span class=\"kw-alerte\">hospitalisation</span>, mais établissement de santé).</li>\n        <li><strong>Anesthésie :</strong>\n          <ul>\n            <li><span class=\"kw-clinique\">Anesthésie générale</span> (consultation préalable requise).</li>\n            <li><span class=\"kw-clinique\">Anesthésie locale</span> paracervicale ou intracervicale.</li>\n          </ul>\n        </li>\n        <li><strong>Évacuation (3 temps) :</strong>\n          <ol>\n            <li>Installation en position gynécologique.</li>\n            <li><strong>Dilatation cervicale</strong> à l’aide de <strong>bougies de calibre croissant</strong>.</li>\n            <li><strong>Aspiration</strong> à l’aide d’une <strong>canule</strong> pour évacuer le contenu utérin.</li>\n          </ol>\n        </li>\n        <li><strong>Contrôle échographique :</strong> non systématique, possible en per-opératoire pour vérifier la vacuité utérine.</li>\n        <li><strong>CAT si échec/rétention :</strong> <span class=\"kw-imagerie\">échographie</span> pour confirmer le diagnostic → <span class=\"kw-clinique\">aspiration</span> ou <span class=\"kw-clinique\">exérèse sous contrôle hystéroscopique</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Choix de la méthode.</strong> Les différences entre les 2 méthodes en termes de succès, EI et lésions d’organes sont <strong>très faibles</strong>. Dans tous les cas où c’est possible, la femme doit pouvoir choisir la méthode (médicale ou instrumentale, anesthésie générale ou locale), quel que soit l’âge gestationnel, après exposé des avantages et inconvénients de chacune.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":2},{"id":"37-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les contre-indications des différentes méthodes","contenu":"<p>Les <span class=\"kw-def\">contre-indications</span> diffèrent selon la méthode (médicamenteuse <span class=\"kw-bio\">vs</span> chirurgicale) et selon le médicament utilisé. Connaître par cœur les <strong>non-CI piégeuses</strong> de l’IVG médicamenteuse.</p>\n\n      <h4>CI spécifiques des médicaments</h4>\n\n      <table >\n        <thead>\n          <tr><th></th><th><span class=\"kw-ttt\">Mifépristone</span></th><th><span class=\"kw-ttt\">Misoprostol</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Contre-indications</span></strong></td>\n            <td>\n              <span class=\"kw-ci\">Allergie connue</span> à la mifépristone ;<br>\n              <span class=\"kw-ci\">Porphyrie héréditaire</span> ;<br>\n              <span class=\"kw-ci\">Insuffisance surrénalienne chronique</span> ;<br>\n              <span class=\"kw-ci\">Traitement corticostéroïde chronique</span> ;<br>\n              <span class=\"kw-ci\">Asthme sévère non équilibré</span> par un traitement.\n            </td>\n            <td>\n              <span class=\"kw-ci\">Allergie</span> au misoprostol ;<br>\n              <span class=\"kw-ci\">Allergie</span> aux prostaglandines ;<br>\n              <span class=\"kw-ci\">Insuffisance rénale</span> ;<br>\n              <span class=\"kw-ci\">Insuffisance hépatique</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Situations à risque (non CI, prudence)</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Insuffisance rénale</span> ;<br>\n              <span class=\"kw-clinique\">Insuffisance hépatique</span> ;<br>\n              <span class=\"kw-clinique\">Malnutrition</span>.\n            </td>\n            <td>\n              <span class=\"kw-clinique\">ATCD cardiovasculaires</span> — précautions d’emploi.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>CI globales de l’IVG médicamenteuse</h4>\n\n      <ul>\n        <li><span class=\"kw-ci\">Anémie profonde</span> <span class=\"kw-chiffre\">&lt; 9 g/dL</span>, <span class=\"kw-ci\">troubles de la coagulation</span>, <span class=\"kw-ci\">anticoagulants</span> (absence de contrôle de l’hémorragie en cas de complication).</li>\n        <li><span class=\"kw-ci\">Grossesse ectopique confirmée ou suspectée</span> :\n          <ul>\n            <li>La <span class=\"kw-ttt\">mifépristone est inefficace sur la GEU</span> par <span class=\"kw-alerte\">absence de récepteurs de la progestérone au niveau des trompes</span>.</li>\n            <li>IVG médicamenteuse possible devant une <span class=\"kw-ci\">grossesse</span> de <strong>localisation inconnue</strong> si : absence de FR de GEU + absence de symptômes de GEU + <span class=\"kw-chiffre\">hCG &lt; 1500 UI</span>.</li>\n          </ul>\n        </li>\n        <li><span class=\"kw-ci\">DIU en place</span> :\n          <ul>\n            <li><strong>Masson :</strong> retrait préférable, mais ne CI pas l’IVG si retrait impossible.</li>\n            <li><strong>Medline :</strong> IVG médicamenteuse <strong>CI si le retrait du DIU est impossible</strong>.</li>\n          </ul>\n        </li>\n        <li><span class=\"kw-ci\">CI organisationnelles</span> : patiente isolée, impossibilité de <span class=\"kw-def\">suivi</span>, ne comprenant pas les informations délivrées.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>PIÈGE QCM — ne sont PAS des CI de l’IVG médicamenteuse.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Allaitement</span></li>\n          <li><span class=\"kw-clinique\">Tabac</span></li>\n          <li><span class=\"kw-clinique\">Obésité</span></li>\n          <li><span class=\"kw-clinique\">Grossesse gémellaire</span></li>\n          <li><span class=\"kw-clinique\">Utérus cicatriciel</span></li>\n        </ul>\n        À connaître par cœur — ce sont les pièges classiques aux QCM.\n      </div>\n\n      <h4>IVG chirurgicale</h4>\n\n      <p>Peu de <span class=\"kw-ci\">CI absolues</span> spécifiques. Essentiellement : <span class=\"kw-ci\">CI anesthésiques classiques</span> si AG prévue (à évaluer en consultation pré-anesthésique), <span class=\"kw-ci\">infection génitale active</span> à traiter au préalable.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 245 — Insuffisance surrénale · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"37-10","rang":"B","rubrique":"Suivi et pronostic","titre":"Connaître les principales complications des IVG chirurgicales et médicamenteuses","contenu":"<p>Complications classées en <span class=\"kw-def\">immédiates</span>, <span class=\"kw-def\">secondaires</span> et <span class=\"kw-def\">à long terme</span>. À connaître : profils différents entre IVG médicamenteuse (saignement, douleur) et chirurgicale (hémorragie, mécaniques).</p>\n\n      <h4>Tableau comparatif IVG instrumentale <span class=\"kw-bio\">vs</span> médicamenteuse</h4>\n\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>IVG instrumentale</th><th>IVG médicamenteuse</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Acteur</strong></td>\n            <td>Médecin ; sage-femme jusqu’à <span class=\"kw-chiffre\">≤ 12</span> SA (2022)</td>\n            <td>Femme (PEC par médecin ou sage-femme)</td>\n          </tr>\n          <tr>\n            <td><strong>Invasif ?</strong></td>\n            <td>Oui</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Anesthésie</strong></td>\n            <td>Locale ou générale (accidents d’anesthésie = complications spécifiques)</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Durée d’évacuation</strong></td>\n            <td>Quelques <span class=\"kw-chiffre\">minutes</span></td>\n            <td>Quelques <span class=\"kw-chiffre\">heures à jours</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Suivi</span></strong></td>\n            <td>Non indispensable</td>\n            <td>Nécessaire (entre <span class=\"kw-chiffre\">J14 - J21</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Succès</strong></td>\n            <td><span class=\"kw-chiffre\">99 %</span></td>\n            <td><span class=\"kw-chiffre\">95-98 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Douleurs</strong></td>\n            <td>\n              Peu (anesthésie).<br>\n              <span class=\"kw-ttt\">Ibuprofène</span> per (<span class=\"kw-chiffre\">600 mg</span>) et post-opératoire ⭐.\n            </td>\n            <td>\n              Absentes à sévères.<br>\n              <span class=\"kw-ttt\">Ibuprofène</span> en <span class=\"kw-chiffre\">1ère intention</span> ⭐.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Saignement</strong></td>\n            <td>Faibles (<span class=\"kw-chiffre\">3-8 jours</span>)</td>\n            <td><span class=\"kw-chiffre\">10-15 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie</strong></td>\n            <td><span class=\"kw-chiffre\">0,5 %</span></td>\n            <td><span class=\"kw-chiffre\">5 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Complications mécaniques</strong></td>\n            <td>\n              <strong>Déchirure cervicale :</strong> <span class=\"kw-chiffre\">0,2 - 1 %</span> ;<br>\n              <strong>Perforation utérine :</strong> <span class=\"kw-chiffre\">1-4 pour 1000</span>.\n            </td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Échec complet</strong></td>\n            <td>Exceptionnel (<span class=\"kw-chiffre\">1-5 / 1000</span>) — si impossibilité de dilater le col, ou aspiration en dehors de la cavité utérine</td>\n            <td>Taux de <span class=\"kw-ci\">grossesse</span> évolutive (échec total) <span class=\"kw-chiffre\">1 %</span> ; échec partiel plus fréquent</td>\n          </tr>\n          <tr>\n            <td><strong>Infection génitale haute (IGH)</strong></td>\n            <td><span class=\"kw-chiffre\">1 %</span></td>\n            <td><span class=\"kw-chiffre\">0,3 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Complications immédiates</h4>\n\n      <ul>\n        <li><strong>Douleur :</strong>\n          <ul>\n            <li>Après misoprostol : <span class=\"kw-ttt\">ibuprofène</span> ou association <span class=\"kw-ttt\">paracétamol + codéine</span> (<span class=\"kw-alerte\">pas de paracétamol seul</span>).</li>\n            <li>Per/post-opératoire IVG chirurgicale : <span class=\"kw-ttt\">AINS</span> pouvant être débutés en pré-opératoire.</li>\n          </ul>\n        </li>\n        <li><strong>Hémorragie :</strong>\n          <ul>\n            <li>Risque : <span class=\"kw-chiffre\">0,5 %</span> après IVG instrumentale ; <span class=\"kw-chiffre\">5 %</span> après IVG médicamenteuse.</li>\n            <li>Différentes présentations :\n              <ul>\n                <li><strong>Hémorragie extériorisée</strong> par lésions cervicales (traction du col lors de l’IVG chirurgicale).</li>\n                <li><strong>Hémorragie extériorisée</strong> par atonie utérine (surtout si temps opératoire prolongé, <span class=\"kw-ci\">grossesse</span> évoluée).</li>\n                <li><span class=\"kw-alerte\">Hémopéritoine</span> lors d’une perforation utérine.</li>\n                <li><strong>Hémorragies secondaires</strong> dans le <span class=\"kw-chiffre\">&lt; 1 mois</span> : IGH, rétention ovulaire, hématométrie résiduelle.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n        <li><strong>Mécaniques</strong> (uniquement IVG chirurgicale, absentes si médicamenteuse) :\n          <ul>\n            <li><span class=\"kw-clinique\">Déchirures cervicales</span> (<span class=\"kw-chiffre\">0,2 - 1 %</span>).</li>\n            <li><span class=\"kw-clinique\">Perforation utérine</span> (<span class=\"kw-chiffre\">1-4 / 1000</span>).</li>\n          </ul>\n        </li>\n        <li><strong>Infectieuses (IGH post-IVG) :</strong>\n          <ul>\n            <li>Risque : <span class=\"kw-chiffre\">1 %</span> après IVG instrumentale ; <span class=\"kw-chiffre\">0,3 %</span> après IVG médicamenteuse.</li>\n            <li>Cause : <span class=\"kw-etio\">vaginose bactérienne</span> ou portage asymptomatique de <span class=\"kw-etio\">gonocoque</span> / <span class=\"kw-etio\">Chlamydia trachomatis</span>.</li>\n            <li>Mesures préventives :\n              <ul>\n                <li><span class=\"kw-alerte\">Pas d’antibioprophylaxie</span> recommandée quelle que soit la technique <em>(LISA indique qu’elle est recommandée si chir)</em>.</li>\n                <li><span class=\"kw-def\">Dépistage</span> par <span class=\"kw-bio\">PCR gonocoque + Chlamydia trachomatis</span> sur prélèvement vaginal (IVG réalisable sans attendre le résultat, mais conseillé).</li>\n                <li>ATB justifiée si prélèvement positif.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n        <li><strong>Décès :</strong> risque du même ordre que la fausse couche spontanée — <span class=\"kw-chiffre\">0,7 / 100 000</span>.</li>\n      </ul>\n\n      <h4>Complications secondaires</h4>\n\n      <ul>\n        <li><span class=\"kw-etio\">Pseudo-anévrysmes</span> : résultat d’un défect pariétal artériel.</li>\n        <li><span class=\"kw-etio\">Malformations artério-veineuses utérines (MAVU)</span> :\n          <ol>\n            <li><strong>Persistance de tissu ovulaire</strong> après une IVG médicamenteuse ou instrumentale.</li>\n            <li><strong>Favorise le défaut de résorption</strong> de la vascularisation péritrophoblastique → création d’une MAVU.</li>\n          </ol>\n        </li>\n        <li><strong>Traitement des 2 entités :</strong> <span class=\"kw-clinique\">embolisation par radiologie interventionnelle</span>.</li>\n      </ul>\n\n      <h4>Complications à long terme</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Pas d’augmentation</strong> du risque de (après 1 ou plusieurs IVG) :\n        <ul>\n          <li>Infertilité.</li>\n          <li>Fausse couche spontanée (<strong>sauf</strong> si intervalle entre l’IVG et la <span class=\"kw-ci\">grossesse</span> suivante <span class=\"kw-chiffre\">&lt; 3 mois</span>).</li>\n          <li><span class=\"kw-ci\">Grossesse</span> extra-utérine.</li>\n          <li>Anomalies de la placentation.</li>\n          <li>Accouchement prématuré.</li>\n          <li>Cancer du sein.</li>\n          <li>Troubles psychiatriques.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 43 — Hémorragie génitale chez la femme · 162 — IST</em></p>","frequence":2},{"id":"37-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les déterminants du choix contraceptif après IVG","contenu":"<p>Le choix de la <span class=\"kw-def\">contraception post-IVG</span> doit tenir compte de : <strong>efficacité, effets secondaires, <span class=\"kw-ci\">contre-indications</span>, coût, contrainte d’utilisation</strong>. L’information se fait à la <span class=\"kw-alerte\">2ème consultation</span>, pas à la 1ère.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Méthodes LARC à privilégier.</strong> Les méthodes contraceptives <span class=\"kw-def\">réversibles à longue durée d’action (LARC)</span> — <span class=\"kw-clinique\">DIU</span> et <span class=\"kw-clinique\">implant</span> — pourraient mieux <strong>prévenir la répétition des IVG</strong>. À mettre en avant lors de la discussion contraceptive post-IVG.\n      </div>\n\n      <h4>Quand commencer la contraception selon la méthode et la technique IVG</h4>\n\n      <table >\n        <thead>\n          <tr><th>Méthode</th><th>Début après IVG instrumentale</th><th>Début après IVG médicamenteuse</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Contraception orale œstroprogestative ou progestative, patch</strong></td>\n            <td><strong>Le jour de l’IVG instrumentale</strong></td>\n            <td>Le <strong>jour ou le lendemain</strong> de la prise du misoprostol</td>\n          </tr>\n          <tr>\n            <td><strong>Anneau vaginal</strong></td>\n            <td><strong>Dans les <span class=\"kw-chiffre\">5 jours</span></strong> qui suivent l’IVG instrumentale</td>\n            <td><strong>Dans la semaine</strong> qui suit la prise de mifépristone</td>\n          </tr>\n          <tr>\n            <td><strong>Implant</strong></td>\n            <td><strong>Insertion le jour de l’IVG instrumentale</strong></td>\n            <td><strong>Insertion possible dès la prise de mifépristone</strong></td>\n          </tr>\n          <tr>\n            <td><strong>DIU et SIU</strong></td>\n            <td><strong>Immédiate</strong> au décours de l’IVG chirurgicale</td>\n            <td><strong>Dans les <span class=\"kw-chiffre\">10 jours</span></strong> après IVG médicamenteuse (<em>après vérification de la vacuité utérine ⭐</em>)</td>\n          </tr>\n          <tr>\n            <td><strong>Méthodes barrières et naturelles</strong></td>\n            <td colspan=\"2\"><strong>Dès la reprise des rapports sexuels</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Synthèse — Le jour même de l’IVG</h4>\n\n      <table >\n        <thead>\n          <tr><th></th><th>IVG chirurgicale</th><th>IVG médicamenteuse</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Jour même</strong></td>\n            <td>\n              <strong>COP :</strong> orale, patch ;<br>\n              <strong>Contraception microprogestative :</strong> orale, implant, <span class=\"kw-clinique\">DIU</span> ;<br>\n              <span class=\"kw-clinique\">DIU cuivre</span>.\n            </td>\n            <td>\n              <strong>COP :</strong> orale, patch ;<br>\n              <strong>Contraception microprogestative :</strong> orale, implant.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Plus tard</strong></td>\n            <td><strong>COP en anneau vaginal :</strong> possible <span class=\"kw-chiffre\">5 jours après</span>.</td>\n            <td>\n              <strong>COP en anneau vaginal :</strong> possible <strong>dans la semaine</strong>.<br>\n              <strong>DIU :</strong> possible <span class=\"kw-chiffre\">10 jours après</span> vérification de la vacuité utérine.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":0},{"id":"37-12","rang":"B","rubrique":"Suivi et pronostic","titre":"Identifier les facteurs de risques de récidive","contenu":"<div class=\"callout callout-info\">\n        <strong>Niveau d’exigence.</strong> Le descriptif officiel CNGOF de cet objectif est <strong>volontairement minimal</strong> : ni la fiche EDN ni le Collège de Gynécologie-Obstétrique ne détaillent de liste de FDR de récidive. Les FDR attendus découlent directement des <strong>causes de grossesses non désirées</strong> (cf. obj-1) — essentiellement une <span class=\"kw-clinique\">contraception absente, mal adaptée ou interrompue</span>.\n      </div>\n\n      <h4>FDR de récidive (dérivés des causes officielles, cf. obj-1)</h4>\n\n      <ul>\n        <li><strong>Échec / oubli / défaut d’utilisation de la contraception</strong> : <span class=\"kw-chiffre\">&gt; 60 %</span> des IVG surviennent chez des femmes <strong>sous contraception</strong> au moment de la <span class=\"kw-ci\">grossesse</span> — c’est le FDR majeur.</li>\n        <li><strong>Méthode contraceptive peu efficace</strong> : méthodes naturelles (Ogino, Billings, MAMA), retrait, préservatif seul → privilégier les <span class=\"kw-clinique\">LARC (DIU, implant)</span> en post-IVG ⭐.</li>\n        <li><strong><span class=\"kw-def\">Vulnérabilité sociale</span></strong> : situations de précarité, isolement, jeunesse, manque d’éducation/d’information.</li>\n        <li><strong><span class=\"kw-clinique\">ATCD d’IVG</span></strong> : la récidive est plus fréquente chez les femmes ayant déjà eu une IVG (à confirmer en source officielle).</li>\n        <li><strong>Non-recours à la consultation contraceptive post-IVG</strong> : manque d’information, perte de vue à <span class=\"kw-chiffre\">J14 - J21</span>.</li>\n        <li><strong>Événements de vie à risque</strong> : <span class=\"kw-clinique\">post-partum</span>, post-IVG, ménopause débutante, changement de partenaire.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Cohérence avec obj-10.</strong> La <strong>prévention de la récidive</strong> repose sur la prescription d’une <span class=\"kw-clinique\">contraception efficace, longue durée d’action (LARC) si possible</span>, dès la 2ème consultation IVG, avec un <strong><span class=\"kw-def\">suivi</span> rapproché</strong> (consultation de contrôle J14-<span class=\"kw-chiffre\">J21</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Délais légaux <span class=\"kw-etio\">médicamenteux</span></strong></p><ul><li><span class=\"kw-ttt\">IVG médicamenteuse</span> : possible jusqu'à <span class=\"kw-chiffre\">7 semaines de grossesse</span> (<span class=\"kw-chiffre\">9 SA</span>)</li><li>En ville jusqu'à <span class=\"kw-chiffre\">9 SA</span> ; au-delà, <span class=\"kw-ci\">uniquement en établissement</span></li></ul><p><strong>Délais légaux chirurgicaux</strong></p><ul><li><span class=\"kw-ttt\">IVG chirurgicale</span> : possible jusqu'à <span class=\"kw-chiffre\">14 semaines de grossesse</span> (<span class=\"kw-chiffre\">16 SA</span>)</li><li><span class=\"kw-ci\">Impossible en ville</span> — établissement agréé (public ou privé) <strong>obligatoire</strong></li></ul><p><strong>Délai d'accès garanti</strong></p><ul><li>Toute patiente appelant un établissement doit obtenir un <span class=\"kw-chiffre\">RDV de consultation dans les 5 jours</span> suivant son appel</li><li>IVG peut se décider <strong>sans délai de réflexion</strong> (suppression du délai de <span class=\"kw-chiffre\">2 jours</span> depuis 2022)</li></ul><p><strong>Immunoglobulines anti-D</strong></p><p>Prescrire systématiquement : <span class=\"kw-bio\">groupe sanguin + Rh + RAI</span> dès la 1ère consultation</p><ul><li>Injection d'<span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">&lt; 72h</span> pour toute IVG si femme <span class=\"kw-etio\">Rh négative</span></li></ul>","hospit":"<p><strong>IVG médicamenteuse en ville <span class=\"q\">— jusqu'à 9 SA</span></strong></p><ul><li>Médecin/SF <strong>conventionné</strong> à un établissement de santé agréé</li><li>Doit être qualifié en <span class=\"kw-def\">gynécologie médicale ou obstétrique</span>, ou justifier d'une pratique suffisante et régulière</li><li><span class=\"kw-ttt\">Mifépristone</span> disponible en pharmacie d'officine (délivrance réservée aux praticiens autorisés)</li></ul><p><strong>IVG en établissement de santé <span class=\"q\">— obligatoire pour la chirurgicale</span></strong></p><ul><li>Établissements publics <span class=\"kw-ci\">ne peuvent pas refuser</span> de pratiquer des IVG</li><li>IVG réalisées en <span class=\"kw-def\">hôpital de jour</span> (séjour <span class=\"kw-chiffre\">&lt; 12h</span>)</li><li>Lits en gynécologie-obstétrique ou <span class=\"kw-ttt\">chirurgie</span> disponibles en cas de complication</li><li><span class=\"kw-def\">Anonymat</span> garanti sur les relevés de sécurité sociale pour les femmes majeures et mineures à l'hôpital</li></ul><p><strong>Clause de conscience</strong></p><ul><li>Médecin/SF n'est pas tenu de pratiquer une IVG</li><li><strong>Obligation</strong> de communiquer immédiatement le nom et les coordonnées d'autres praticiens si refus</li></ul>","principes":"<p>Démarche en <strong>2 consultations</strong> : 1ère consultation (formulation de la demande) + 2ème consultation (confirmation + réalisation). Bilan initial systématique : <span class=\"kw-bio\">groupe sanguin ABO + Rh + RAI</span> · <span class=\"kw-bio\">PCR Chlamydia trachomatis + gonocoque</span> sur prélèvement vaginal. Consentement <strong>écrit</strong> de la femme (pas du conjoint). <span class=\"kw-ci\">GEU confirmée ou suspectée = contre-indication à l'IVG médicamenteuse</span> (absence de récepteurs à la progestérone dans les trompes).</p><p><strong>IVG médicamenteuse — protocole</strong></p><ul><li><strong><span class=\"kw-chiffre\">J0</span> :</strong> <span class=\"kw-ttt\">mifépristone</span> per os (anti-progestérone) au terme de la 2ème consultation</li><li><strong><span class=\"kw-chiffre\">J1</span>-J2 :</strong> <span class=\"kw-ttt\">misoprostol</span> (analogue PGE1) par voie transmuqueuse orale ou sublinguale, <span class=\"kw-chiffre\">24-48h</span> après la mifépristone</li><li>Expulsion survient le plus souvent <span class=\"kw-chiffre\">2-4h</span> après la prise de misoprostol (<span class=\"kw-chiffre\">60 %</span> des cas)</li><li>Taux de succès : <span class=\"kw-chiffre\">95-98 %</span> — taux d'échec global <span class=\"kw-chiffre\">5 %</span> (<span class=\"kw-ci\">grossesse</span> évolutive résiduelle <span class=\"kw-chiffre\">&lt; 1 %</span>)</li></ul><p><strong>IVG chirurgicale — protocole</strong></p><p><span class=\"kw-ci\">IVG chirurgicale impossible en ville</span> : établissement agréé obligatoire</p><ul><li><span class=\"kw-ttt\">Préparation cervicale</span> systématiquement recommandée (<span class=\"kw-ttt\">mifépristone</span> ou <span class=\"kw-ttt\">misoprostol</span> délivré <span class=\"kw-chiffre\">36-48h</span> avant)</li><li>Technique : <strong>dilatation cervicale</strong> (bougies de calibre croissant) puis <strong>aspiration</strong> (canule)</li><li>Anesthésie locale paracervicale ou générale (consultation d'anesthésie si AG prévue)</li><li>Taux de succès : <span class=\"kw-chiffre\">&gt; 99 %</span> ; complications mécaniques rares (<span class=\"kw-etio\">perforation utérine</span> <span class=\"kw-chiffre\">1-4/1000</span>)</li></ul><p><strong><span class=\"kw-ci\">Contre-indications</span> à l'IVG médicamenteuse</strong></p><ul><li><span class=\"kw-ci\">GEU confirmée ou suspectée</span> (mifépristone inefficace sur les trompes)</li><li><span class=\"kw-ci\">Anémie profonde &lt; 9 g/dL</span>, troubles de la coagulation, <span class=\"kw-ttt\">anticoagulants</span></li><li><span class=\"kw-ci\">DIU en place</span> si retrait impossible</li><li><span class=\"kw-ci\">Contre-indications organisationnelles</span> : isolement, impossibilité de <span class=\"kw-def\">suivi</span></li><li>Non-CI : <span class=\"kw-ci\">allaitement</span>, tabac, <span class=\"kw-etio\">obésité</span>, grossesse gémellaire, utérus cicatriciel</li></ul>","suivi":"<p><strong>Consultation de contrôle : </strong> <span class=\"kw-chiffre\">J14-J21</span> après l'IVG — vérification de la vacuité utérine (<span class=\"kw-imagerie\">contrôle échographique</span> ou <span class=\"kw-bio\">β-hCG</span> : succès si baisse <span class=\"kw-chiffre\">&gt; 80 %</span> à <span class=\"kw-chiffre\">J15</span> versus dosage initial) + bilan de la contraception + recherche de complications.</p><p><strong>Contraception post-IVG</strong></p><ul><li>Information et choix de la méthode contraceptive lors de la <strong>2ème consultation</strong> (pas la 1ère)</li><li><span class=\"kw-ttt\">Contraception orale / patch</span> : possible <strong>le jour même de l'IVG</strong></li><li><span class=\"kw-ttt\">Implant</span> : insertion le jour de l'IVG instrumentale ou dès la prise de mifépristone</li><li><span class=\"kw-ttt\">DIU</span> : immédiat après IVG chirurgicale ; <span class=\"kw-chiffre\">10 jours</span> après IVG médicamenteuse (après vérification vacuité)</li><li><span class=\"kw-ttt\">Anneau vaginal</span> : <span class=\"kw-chiffre\">5 jours</span> après IVG instrumentale ou dans la semaine après mifépristone</li></ul><p><strong>Signes d'alerte à surveiller</strong></p><ul><li><span class=\"kw-alerte\">Hémorragie prolongée</span> ou <strong>saignements au-delà du retour de règles</strong> → évoquer rétention ovulaire</li><li>CAT si rétention : <span class=\"kw-imagerie\">échographie</span> confirmatrice puis <span class=\"kw-ttt\">aspiration</span> ou <span class=\"kw-ttt\">exérèse</span> sous contrôle <span class=\"kw-imagerie\">hystéroscopique</span></li><li><span class=\"kw-alerte\">Infection génitale haute (IGH)</span> post-IVG : <span class=\"kw-chiffre\">1 %</span> après chirurgicale, <span class=\"kw-chiffre\">0,3 %</span> après médicamenteuse</li><li><span class=\"kw-def\">Dépistage</span> préventif : <span class=\"kw-bio\">PCR Gonocoque et Chlamydia</span> avant toute IVG (ATB si prélèvement positif)</li></ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Demande d'IVG — terme (SA) ? — Préciser : terme en semaines d'aménorrhée (SA) + Rhésus maternel","detail":"<h4>CAT — choix de méthode d'IVG selon le terme — Arbre orienté par le terme (SA), les <span class=\"kw-ci\">contre-indications</span> à la méthode médicamenteuse et le lieu de réalisation</h4>","branches":[{"to":"t-hors-delai","label":"Hors délai légal (> 16 SA)","color":"red"},{"to":"t-chirurgicale-etab","label":"> 9 SA et ≤ 16 SA","color":"blue"},{"to":"q-ci-med","label":"≤ 9 SA","color":"green"}]},{"id":"t-hors-delai","kind":"terminal","label":"Hors délai légal — IVG impossible en France","color":"red","detail":"<h4>Délais légaux</h4><ul><li><span class=\"kw-chiffre\">IVG médicamenteuse</span> autorisée jusqu'à <span class=\"kw-chiffre\">9 SA</span> (<span class=\"kw-chiffre\">7 semaines de grossesse</span>)</li><li><span class=\"kw-chiffre\">IVG chirurgicale</span> autorisée jusqu'à <span class=\"kw-chiffre\">16 SA</span> (<span class=\"kw-chiffre\">14 semaines de grossesse</span>)</li></ul><h4>CAT</h4><ul><li>Prise en charge spécialisée — <span class=\"kw-alerte\">délai légal dépassé</span> en France ; orientation vers structure compétente (interruption médicale de <span class=\"kw-ci\">grossesse</span> si indication médicale).</li></ul>"},{"id":"t-chirurgicale-etab","kind":"terminal","label":"IVG chirurgicale — établissement agréé obligatoire","color":"blue","detail":"<h4>Méthode</h4><ul><li><span class=\"kw-ttt\">Préparation cervicale</span> : <span class=\"kw-ttt\">mifépristone</span> ou <span class=\"kw-ttt\">misoprostol</span> délivré <span class=\"kw-chiffre\">36-48h</span> avant</li><li><span class=\"kw-ttt\">Dilatation cervicale</span> (bougies) puis <span class=\"kw-ttt\">aspiration</span> (canule)</li><li>Anesthésie locale ou générale (consultation anesthésie si AG)</li></ul><h4>Lieu</h4><ul><li><span class=\"kw-ci\">Impossible en ville</span> — établissement public ou privé de santé agréé <strong>obligatoire</strong></li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li>Consultation de contrôle <span class=\"kw-chiffre\">J14-J21</span> + vérification vacuité utérine + contraception</li></ul><h4>Anti-D</h4><ul><li>Si <span class=\"kw-etio\">Rh négatif</span> : <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">&lt; 72h</span></li></ul>"},{"id":"q-ci-med","kind":"decision","label":"<span class=\"kw-ci\">Contre-indication</span> à l'IVG médicamenteuse ? — GEU confirmée/suspectée · anémie < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>9</span> g/dL</span> · <span class=\"kw-ttt\">anticoagulants</span> · DIU impossible à retirer · isolement/impossibilité de <span class=\"kw-def\">suivi</span>","branches":[{"to":"q-ci-chir-terme","label":"Oui — CI médicamenteuse présente","color":"amber"},{"to":"q-lieu","label":"Non — pas de CI médicamenteuse","color":"green"}]},{"id":"q-ci-chir-terme","kind":"decision","label":"Terme ≤ 16 SA et pas de CI chirurgicale ?","branches":[{"to":"t-chir-apres-ci","label":"Oui — chirurgicale possible","color":"blue"},{"to":"t-ci-totale","label":"Non — CI aux deux méthodes","color":"red"}]},{"id":"t-chir-apres-ci","kind":"terminal","label":"IVG chirurgicale — établissement agréé (CI médicamenteuse)","color":"blue","detail":"<h4>Indication</h4><ul><li>Méthode médicamenteuse <span class=\"kw-ci\">contre-indiquée</span> → recours chirurgical en établissement agréé</li></ul><h4>Technique</h4><ul><li><span class=\"kw-ttt\">Préparation cervicale</span> (<span class=\"kw-ttt\">mifépristone</span> ou <span class=\"kw-ttt\">misoprostol</span> <span class=\"kw-chiffre\">36-48h</span> avant)</li><li><span class=\"kw-ttt\">Aspiration</span> après dilatation cervicale</li></ul><h4>Anti-D</h4><ul><li>Si <span class=\"kw-etio\">Rh négatif</span> : <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">&lt; 72h</span></li></ul>"},{"id":"t-ci-totale","kind":"terminal","label":"CI aux deux méthodes — avis spécialisé","color":"red","detail":"<h4>CAT</h4><ul><li>Orientation vers centre pluridisciplinaire ; <span class=\"kw-alerte\">CI médicale et/ou organisationnelle aux deux méthodes</span> — prise en charge individualisée.</li></ul>"},{"id":"q-lieu","kind":"decision","label":"Lieu souhaité / possible ? — Vérifier : praticien conventionné à un établissement agréé disponible en ville","branches":[{"to":"t-med-ville","label":"Ville — praticien conventionné disponible (≤ 9 SA)","color":"green"},{"to":"t-med-etab","label":"Établissement (choix patiente ou praticien ville indisponible)","color":"green"}]},{"id":"t-med-ville","kind":"terminal","label":"IVG médicamenteuse en ville","color":"green","detail":"<h4>Protocole</h4><ul><li><strong><span class=\"kw-chiffre\">J0</span> :</strong> <span class=\"kw-ttt\">mifépristone</span> per os au terme de la 2ème consultation</li><li><strong><span class=\"kw-chiffre\">J1</span>-J2 :</strong> <span class=\"kw-ttt\">misoprostol</span> sublingual ou transmuqueux oral (<span class=\"kw-chiffre\">24-48h</span> après)</li><li>Expulsion en <span class=\"kw-chiffre\">2-4h</span> après misoprostol dans <span class=\"kw-chiffre\">60 %</span> des cas</li></ul><h4><span class=\"kw-ttt\">Antalgiques</span></h4><ul><li><span class=\"kw-ttt\">Ibuprofène</span> en <span class=\"kw-chiffre\">1ère intention</span> pour les douleurs de contraction</li></ul><h4><span class=\"kw-def\">Suivi</span> obligatoire</h4><ul><li>Consultation de contrôle <span class=\"kw-chiffre\">J14-J21</span> : <span class=\"kw-bio\">β-hCG</span> (succès si baisse <span class=\"kw-chiffre\">&gt; 80 %</span>) ou <span class=\"kw-imagerie\">échographie</span> de vacuité</li></ul><h4>Anti-D</h4><ul><li>Si <span class=\"kw-etio\">Rh négatif</span> : <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">&lt; 72h</span></li></ul>"},{"id":"t-med-etab","kind":"terminal","label":"IVG médicamenteuse en établissement","color":"green","detail":"<h4>Protocole</h4><ul><li>Identique à la ville : <span class=\"kw-ttt\">mifépristone</span> <span class=\"kw-chiffre\">J0</span> + <span class=\"kw-ttt\">misoprostol</span> <span class=\"kw-chiffre\">J1</span>-J2</li><li>IVG réalisée en <span class=\"kw-def\">hôpital de jour</span> (séjour <span class=\"kw-chiffre\">&lt; 12h</span>)</li></ul><h4>Choix méthode</h4><ul><li>La patiente peut choisir méthode médicamenteuse <strong>ou</strong> chirurgicale à ce terme selon ses préférences et les <span class=\"kw-ci\">contre-indications</span></li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li>Consultation de contrôle <span class=\"kw-chiffre\">J14-J21</span> + contraception + <span class=\"kw-bio\">β-hCG</span> ou <span class=\"kw-imagerie\">échographie</span></li></ul><h4>Anti-D</h4><ul><li>Si <span class=\"kw-etio\">Rh négatif</span> : <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">&lt; 72h</span></li></ul>"}]},"cards":[{"i":"290a08452b7a","n":37,"o":"37-1","u":"Définition","t":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","q":"Quel était le statut de l'avortement en France avant la loi Veil de 1975, et quelles en étaient les conséquences ?","a":"<p>Avant 1975, l'avortement était un acte <strong>réprimé par la loi</strong> et passible de prison. Cela entraînait un grand nombre d'<strong>avortements clandestins</strong>, responsables de <strong>plus de 250 décès</strong> de femmes par an.</p>"},{"i":"5ce4e57a204d","n":37,"o":"37-1","u":"Définition","t":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","q":"Quelle loi française a autorisé la contraception et en quelle année ?","a":"<p>La <strong>loi Neuwirth</strong> a autorisé la contraception en France en <strong>1967</strong>. Ses décrets d'application n'ont été effectifs qu'à partir de 1974.</p>"},{"i":"eb901802ba6b","n":37,"o":"37-1","u":"Définition","t":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","q":"Quel est l'impact de la loi Veil de 1975 sur l'Interruption Volontaire de Grossesse (IVG) en France ?","a":"<p>La loi Veil du 17 janvier 1975 a <strong>dépénalisé</strong> l'Interruption Volontaire de Grossesse (IVG) en France. Il est important de noter qu'elle ne l'a pas légalisée, mais bien dépénalisée.</p>"},{"i":"f93a55ca4e9d","n":37,"o":"37-1","u":"Définition","t":"Connaître l’histoire politique et sociale qui a mené à la loi sur l’interruption volontaire de grossesse (IVG) de 1975","q":"Quelle évolution juridique majeure concernant l'Interruption Volontaire de Grossesse (IVG) est intervenue le 8 mars 2024 en France ?","a":"<p>Le 8 mars 2024, une <strong>loi constitutionnelle</strong> a inscrit la <strong>liberté garantie des femmes de recourir à l'IVG</strong> dans la Constitution de 1958. La France est le premier pays à inscrire cette liberté au niveau constitutionnel.</p>"},{"i":"4b49c9af9386","n":37,"o":"37-2","u":"Étiologies","t":"Connaître les causes de grossesses non désirées","q":"L'absence de contraception est-elle la principale explication des grossesses non désirées ?","a":"<p>Non. Il est important de retenir que <strong>plus de 60 %</strong> des femmes réalisant une IVG avaient une couverture contraceptive en début de grossesse. L'<strong>échec ou l'inadaptation de la contraception</strong> prime donc sur l'absence de contraception.</p>"},{"i":"bee0c3efd8ae","n":37,"o":"37-2","u":"Étiologies","t":"Connaître les causes de grossesses non désirées","q":"Quelles sont les trois causes officielles (CNGOF) de grossesses non désirées ?","a":"<ul><li><strong>Absence de contraception</strong>.</li><li><strong>Changement de méthode contraceptive</strong> : la période de transition est à risque.</li><li><strong>Méthode non adaptée</strong> : méthode peu efficace ou mal utilisée au regard du mode de vie (ex : oubli de pilule, retard de patch/anneau, retrait, méthodes naturelles).</li></ul>"},{"i":"db9d22876673","n":37,"o":"37-2","u":"Étiologies","t":"Connaître les causes de grossesses non désirées","q":"Selon le CNGOF, quelle est la première cause de grossesse non désirée ?","a":"<p>La première cause est l'<strong>échec ou l'inadaptation de la contraception</strong>. Environ <strong>deux tiers</strong> des femmes ayant recours à une IVG utilisaient une méthode contraceptive au moment de la grossesse.</p>"},{"i":"82867c5ee8f9","n":37,"o":"37-4","u":"Epidémiologie","t":"Connaître l’âge de la population réalisant le plus d’IVG","q":"Quelle est l'explication principale de la baisse de l'incidence de l'Interruption Volontaire de Grossesse (IVG) chez les adolescentes en France ?","a":"<p>La baisse de l'incidence de l'IVG chez les adolescentes est principalement due à l'<strong>amélioration de l'accès à la contraception</strong> et à la <strong>contraception d'urgence</strong> (par exemple, Norlevo/EllaOne en accès libre et gratuité pour les moins de 26 ans).</p>"},{"i":"d4306536bc08","n":37,"o":"37-4","u":"Epidémiologie","t":"Connaître l’âge de la population réalisant le plus d’IVG","q":"Comment a évolué l'incidence de l'Interruption Volontaire de Grossesse (IVG) chez les femmes de 20 à 25 ans et chez les femmes plus âgées en France ?","a":"<ul><li>Chez les femmes de <strong>20-25 ans</strong> : l'incidence est <strong>stable</strong>.</li><li>Chez les <strong>femmes plus âgées</strong> : l'incidence est <strong>en hausse</strong>.</li></ul>"},{"i":"feffa8bed0d1","n":37,"o":"37-4","u":"Epidémiologie","t":"Connaître l’âge de la population réalisant le plus d’IVG","q":"Quelle est la tranche d'âge la plus concernée par le recours à l'Interruption Volontaire de Grossesse (IVG) en France ?","a":"<p>La tranche d'âge la plus concernée par le recours à l'IVG en France est <strong>20-29 ans</strong>.</p>"},{"i":"ff9c341d543c","n":37,"o":"37-4","u":"Epidémiologie","t":"Connaître l’âge de la population réalisant le plus d’IVG","q":"Comment a évolué l'incidence de l'Interruption Volontaire de Grossesse (IVG) chez les femmes de moins de 20 ans en France ?","a":"<p>L'incidence de l'IVG chez les femmes de <strong>moins de 20 ans</strong> est <strong>en baisse</strong>.</p>"},{"i":"3aa420e9903d","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"À quel moment l'information et l'accès à la contraception sont-ils proposés après une IVG en France ?","a":"<p>L'information et l'accès à la contraception sont proposés lors d'une <strong>consultation dédiée à l'issue de l'IVG</strong>. Il est important de noter que cette information se fait lors de la <strong>deuxième consultation</strong>, et non la première.</p>"},{"i":"4691e44b270c","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Quel est le délai de réflexion légal avant de prendre la décision d'une IVG en France ?","a":"<p>Depuis 2022, l'IVG peut se décider <strong>sans aucun délai</strong>. Le délai de 2 jours après l'entretien psychosocial a été supprimé.</p>"},{"i":"740e9ec0c2bf","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Dans quelles situations l'entretien psychosocial est-il obligatoire avant une IVG en France ?","a":"<p>L'entretien psychosocial est <strong>proposé systématiquement</strong> à toute femme avant une IVG. Il est <strong>obligatoire uniquement pour la femme mineure non émancipée</strong>.</p>"},{"i":"8cbc6e24feb6","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Quelles sont les spécificités de la prise en charge d'une IVG pour une femme mineure non émancipée en France ?","a":"<ul><li>Elle doit être <strong>obligatoirement accompagnée par une personne majeure</strong> de son choix (pas nécessairement les représentants légaux).</li><li>L'<strong>entretien psychosocial est obligatoire</strong> pour elle.</li><li>Le rôle de la personne majeure accompagnante est uniquement d'aide et de soutien, sans responsabilité civile ou pénale.</li></ul>"},{"i":"d7d6afad4022","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Quelles sont les conditions de validité du consentement pour une IVG en France ?","a":"<p>Pour une IVG en France, le consentement doit être le <strong>consentement écrit de la femme uniquement</strong>. Le conjoint peut participer à la consultation si la femme le souhaite, mais le consentement est recueilli en dehors de sa présence.</p>"},{"i":"e1f3eff3b123","n":37,"o":"37-5","u":"Définition","t":"Connaître les conditions de pratique des IVG en France","q":"Comment une IVG est-elle prise en charge financièrement en France ?","a":"<p>L'IVG est prise en charge à <strong>100 % par l'Assurance maladie</strong>. Cette prise en charge inclut l'IVG elle-même, l'échographie préalable, l'échographie de contrôle et le bilan sanguin.</p>"},{"i":"116e7e328934","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Quelles sont les obligations des établissements de santé concernant la prise en charge des interruptions volontaires de grossesse (IVG) ?","a":"<p>Les <strong>établissements publics ne peuvent pas refuser</strong> de pratiquer des IVG. Ils doivent disposer :</p><ul><li>D'une <strong>ligne téléphonique dédiée</strong> à cette activité.</li><li>De la garantie qu'une patiente obtient un rendez-vous de consultation dans les <strong>5 jours</strong> suivant son appel.</li><li>De lits en gynécologie-obstétrique ou en chirurgie pour d'éventuelles complications.</li><li>L'IVG est généralement réalisée en <strong>hôpital de jour</strong> (séjour < 12 h).</li></ul><p>L'IVG chirurgicale est <strong>interdite en ville</strong> et ne peut être réalisée qu'en établissement de santé public ou privé agréé.</p>"},{"i":"2db001f0d71e","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Comment la clause de conscience et l'entrave à l'IVG sont-elles régulées par la loi française ?","a":"<ul><li><strong>Clause de conscience</strong> : Le médecin ou la sage-femme <strong>n'est pas tenu de pratiquer une IVG</strong>. En cas de refus, il a l'<strong>obligation de communiquer immédiatement</strong> les coordonnées d'autres praticiens ou sages-femmes susceptibles de la réaliser.</li><li><strong>Entrave à l'IVG</strong> : Empêcher ou tenter d'empêcher une IVG par menace ou diffusion d'allégations à but dissuasif est un <strong>délit sanctionnable</strong> par la loi.</li></ul>"},{"i":"4bf05b040061","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Quels professionnels de santé sont habilités à réaliser une interruption volontaire de grossesse (IVG) médicamenteuse et chirurgicale, et sous quelles conditions ?","a":"<p>Les professionnels habilités sont :</p><ul><li><strong>Médecin</strong> : peut réaliser toutes les consultations et toutes les techniques d'IVG.</li><li><strong>Sage-femme</strong> : peut réaliser toutes les consultations, à l'exception de la 2ème consultation pour IVG chirurgicale au-delà de 12 SA (réservée au médecin). Elle peut pratiquer l'IVG médicamenteuse et l'IVG chirurgicale jusqu'à <strong>12 SA</strong> inclus (depuis 2022).</li></ul>"},{"i":"7f0d9deb24ac","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Dans quelles structures une interruption volontaire de grossesse (IVG) médicamenteuse peut-elle être réalisée en ville et quelles sont les conditions d'habilitation des professionnels ?","a":"<p>L'IVG médicamenteuse peut être réalisée <strong>en ville</strong> jusqu'à 9 SA. La <strong>Mifépristone</strong> est disponible en pharmacie d'officine, délivrée exclusivement par les médecins ou sages-femmes autorisés. Pour être habilités, le médecin ou la sage-femme doit être <strong>conventionné à un établissement de santé</strong> et soit :</p><ul><li>Être qualifié en <strong>gynécologie médicale ou en gynécologie-obstétrique</strong>.</li><li>Justifier d'une pratique suffisante et régulière des IVG médicamenteuses en établissement de santé.</li></ul>"},{"i":"8c3c0df0c323","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Quels sont les différents délais légaux pour la réalisation d'une interruption volontaire de grossesse (IVG) et les techniques associées ?","a":"<p>Le délai maximal pour une IVG dépend de la technique utilisée :</p><ul><li><strong>IVG médicamenteuse</strong> : jusqu'à <strong>7 semaines de grossesse</strong> (soit 9 SA).</li><li><strong>IVG chirurgicale</strong> : jusqu'à <strong>14 semaines de grossesse</strong> (soit 16 SA).</li></ul>"},{"i":"f05914ed12d2","n":37,"o":"37-6","u":"Prise en charge","t":"Connaître les structures de prise en charge des IVG","q":"Dans quelles situations l'anonymat est-il garanti pour les interruptions volontaires de grossesse (IVG) en ville et à l'hôpital ?","a":"<ul><li><strong>En ville</strong> : L'anonymat est garanti <strong>uniquement pour les femmes mineures</strong>.</li><li><strong>À l'hôpital</strong> : L'hospitalisation peut garantir l'anonymat sur les relevés de sécurité sociale pour les <strong>femmes majeures et mineures</strong>.</li></ul>"},{"i":"148468e8b0d3","n":37,"o":"37-7","u":"Prise en charge","t":"Décrire les étapes de la prise en charge","q":"Quels sont les éléments clés de la deuxième consultation d'IVG et les particularités de l'information contraceptive ?","a":"<p>La 2ème consultation d'IVG comprend :</p><ul><li>La <strong>vérification de la datation</strong> (IVG autorisée si LCC ≤ 90 mm et/ou BIP ≤ 30 mm).</li><li>Le recueil du <strong>consentement écrit</strong>.</li><li>La <strong>réalisation de l'IVG</strong> (médicamenteuse ou chirurgicale).</li><li>L'<strong>information et le choix de la méthode contraceptive post-IVG</strong>, qui se fait lors de cette 2ème consultation (et non la 1ère).</li><li>Les <strong>prescriptions</strong> : Ig anti-D si femme Rh-, antalgiques (AINS), contraception choisie.</li></ul>"},{"i":"8bb9d6bb7896","n":37,"o":"37-7","u":"Prise en charge","t":"Décrire les étapes de la prise en charge","q":"Quelles sont les trois consultations clés dans la prise en charge de l'interruption volontaire de grossesse (IVG) ?","a":"<p>La prise en charge de l'IVG suit un schéma en <strong>trois consultations standardisées</strong> :</p><ul><li>La <strong>1ère consultation</strong> : formulation de la demande.</li><li>La <strong>2ème consultation</strong> : confirmation et réalisation de l'IVG.</li><li>La <strong>consultation de contrôle post-IVG</strong>.</li></ul>"},{"i":"bb9586d9308f","n":37,"o":"37-7","u":"Prise en charge","t":"Décrire les étapes de la prise en charge","q":"Quels sont les éléments clés de la première consultation d'IVG (formulation de la demande) ?","a":"<p>La 1ère consultation permet la formulation de la demande d'IVG et comprend :</p><ul><li>Des <strong>informations</strong> sur les procédures, le choix de l'anesthésie.</li><li>Un <strong>entretien psychosocial</strong> proposé systématiquement, obligatoire pour les mineures non émancipées.</li><li>La remise d'un <strong>dossier-guide</strong> et d'une attestation de la 1ère consultation.</li><li>Des <strong>prescriptions</strong> : groupe sanguin (ABO, Rh, RAI), échographie de datation si doute, PCR <em>Chlamydia trachomatis</em> et gonocoque (recommandé).</li></ul>"},{"i":"dc04dd1e26f0","n":37,"o":"37-7","u":"Prise en charge","t":"Décrire les étapes de la prise en charge","q":"Quand et quels sont les objectifs de la consultation de contrôle post-IVG ?","a":"<p>La consultation de contrôle post-IVG a lieu entre <strong>J14 et J21</strong> après l'IVG. Elle est considérée comme <strong>obligatoire</strong> selon certaines références.</p><p>Ses objectifs sont de :</p><ul><li>Vérifier la <strong>réussite de l'IVG</strong> (contrôle β-hCG ou échographique de vacuité utérine).</li><li>Faire le point sur la <strong>contraception</strong> prescrite.</li><li>Rechercher d'éventuelles <strong>complications</strong>.</li></ul>"}]};